    'ffg.td.r6c3': '低至 $7.72',
    'ffg.p.pricingMeans': '<strong>这对你的定价意味着什么：</strong>如果你卖的商品天然成套（组合装、套装，或者经常被一起买走的商品），引导多件订单最多能把单件履约成本压低约 57%（4–8 oz，每单 4 件以上）。这是 TikTok Shop 上最容易拉的利润杠杆之一。',
    'ffg.h2.storage': '仓储费',
    'ffg.p.free60': '<strong>前 60 天仓储免费。</strong>从第 61 天起，FBT 按每立方英尺<em>每天</em>计费，费率随库存放了多久而上涨。2025 年 12 月 15 日生效的费率卡：',
    'ffg.th.days': '仓储天数',
    'ffg.th.rate': '费率（每立方英尺每天）',
    'ffg.td.d30': '30 天以内',
    'ffg.td.d30rate': '免费',
    'ffg.td.d31': '31–60 天',
    'ffg.td.d61': '61–90 天',
    'ffg.td.d91': '91–120 天',
    'ffg.td.d121': '121–180 天',
    'ffg.td.d181': '181–270 天',
    'ffg.td.d271': '271–365 天',
    'ffg.td.d365': '超过 365 天',
    'ffg.p.threeDetails': '有三个细节决定你实际拿到的账单。费用按<strong>每天 23:59</strong>、按你所有单件商品的总立方英尺数计算，<em>可售件和残次品都算在内</em> —— 受损库存在被移出或弃掉之前会一直计费。时长按<strong>出库时间 − 入库时间</strong>计算，所以计时从仓库收到货物开始，而不是从面单创建时开始。最低计费体积是每个 SKU 每天 0.001 立方英尺，这只对非常小的商品有影响。',
    'ffg.p.monthlyBasis': '换算成同一个按月口径，61–180 天的档位大约是每立方英尺每月 $0.90–$1.80，180 天以上的老库存档位大约是 $3.60–$8.10。Amazon FBA 公布的标准价是每立方英尺 $0.78、第四季度是 $2.40，但 FBA 按月计费而 FBT 按天计费 —— 只有两者落到同一口径上才能比较。',
    'ffg.p.claimFix': '有一个说法值得在你看到它的地方纠正：卖家指南经常引用一个固定的<em>每月</em>每立方英尺数字，再加上一句 FBT 没有老库存附加费。这个数字本身大致是中间档位费率折算成一个月 —— 但它就停在这里，而这正是误导人的地方。费率卡是按天计费的，库龄已经被算进价格里，所以一件存放超过 180 天的商品要付上好几倍那个「典型」数字，而存放超过一年的要付第 61 天费率的九倍。把你自己的箱型和存放周期过一遍<a href="/tools/tiktok-fbt-storage-calculator/">FBT 仓储费计算器</a>，再决定那些走不动的批次该怎么办：<a href="/blog/tiktok-shop-fbt-dead-stock-2026/">呆滞库存：什么时候打折比等待更划算</a>。',
    'ffg.h2.returns': 'FBT 退货处理费（2026 年 6 月）',
    'ffg.p.retIntro': '从<strong>2026 年 6 月 1 日</strong>起，TikTok Shop 对 FBT 库存开始强制收取逐件退货处理费。此前，基础退货接收基本被打包进基础履约里，但服装和美妆类目的高退货率促成了这套结构化费用：',
