    'ffg.td.placement.fbt': '每件 $0.30–$2.30',
    'ffg.p.structurally': 'FBT 在结构上比 Amazon FBA 简单 —— 单独列出的附加费更少，库龄算在仓储费率卡里而不是一项独立惩罚，还有一段免费仓储窗口。但 TikTok 的履约网络更小，这意味着某些地区的送达可能比 Amazon 庞大的仓库覆盖更慢（<a href="https://hyperfocus.tech/resources/tiktok-shop-fbt-guide" target="_blank" rel="noopener">来源：hyperfocus.tech</a>）。',
