    'rr.td.wellness': '保健与补充剂',
    'rr.td.wellnessWhy': '消耗品、复购',
    'rr.td.lowRisk': '低风险',
    'rr.td.jewelry': '珠宝与配饰',
    'rr.td.jewelryWhy': '品质与预期不符、材质廉价',
    'rr.td.moderateHigh': '中高风险',
    'rr.h2.realCost': '一次退货的真实成本',
    'rr.p.oneReturn': '当买家退回一件 50 美元的商品时，你实际损失的是这些（<a href="https://hyperfocus.tech/resources/tiktok-shop-returns-disputes" target="_blank" rel="noopener">来源：hyperfocus.tech，2026</a>）：',
    'rr.p.rateCard': '下面的数字用的是 2026 年 6 月 1 日的 FBT 费率卡，它按退回的单件商品收取退货处理费，而不是每单固定 3 美元。',
    'rr.th.item': '成本项目',
    'rr.th.amount': '金额',
    'rr.td.lostRevenue': '损失的销售收入',
    'rr.td.refundFee': '退款管理费（$3 推荐费的 20%）',
    'rr.td.fbtFee': 'FBT 退货处理费（非验货）',
    'rr.td.returnShipping': '退货运费（卖家承担）',
    'rr.td.lostCogs': '损失的 COGS（若无法二次销售）',
    'rr.td.totalCost': '一次退货的总成本',
    'rr.td.plusProfit': '另加：这笔销售损失的利润',
    'rr.td.trueCost': '一次退货的真实成本',
    'rr.p.that': '这就是原售价的 66.6% 没了。而且这还假设商品能按非验货费率处理。验货、重新包装、弃置和退回商家等路径可能改按 $1.00、$0.50、$0.40 或 $0.35 收费 &mdash; 所以去<a href="/rate-updates/">我们的费率更新日志</a>里确认适用的路径。',
    'rr.h2.why': '为什么 TikTok Shop 的退货率更高',
    'rr.p.threeFactors': '相比 Amazon 或传统电商，有三个结构性因素推高了 TikTok Shop 的退货率：',
    'rr.p.factor1': '<strong>1. 冲动购买机制。</strong>TikTok Shop 的发现模型建立在刷到即买的行为上。一条达人视频触发情绪反应，购买按钮只有一下之遥。没有搜索框，没有比价，没有审慎考虑。这笔退货就是买家的后悔心态，通过 TikTok 宽松的退货政策处理。',
    'rr.p.factor2': '<strong>2. 达人带来的预期落差。</strong>达人被激励着把商品拍得尽可能吸引人。beauty 滤镜能让粉底看起来完美，一个巧妙的拍摄角度能让一件首饰显得厚实。商品到手和视频里对不上，退货率就会飙升。这在时尚和配饰类目尤其严重，那里有 20-40% 的订单被退回（<a href="https://bemomentiq.com/blog/category/tiktok-shop" target="_blank" rel="noopener">来源：MomentIQ，2026</a>）。',
    'rr.p.factor3': '<strong>3. 更低的购买意图。</strong>Amazon 的购物者带着明确的商品目标而来。他们搜索、比价、看评价，然后才下单。TikTok Shop 的买家是冲着娱乐内容进来的 &mdash; 购买只是视频之外的附带。购买意图更低，就意味着退货概率更高。',
    'rr.h2.margin': '退货如何影响你的利润率',
    'rr.p.compounding': '在 30% 的退货率下，光退款管理费一项就能从你的净利里削掉 1-2%（<a href="https://margn.shop/blog/tiktok-shop-profit-margin-benchmarks" target="_blank" rel="noopener">来源：Margn，2026</a>）。但真正的伤害在于复利效应：',
    'rr.p.example': '<strong>举例：30 美元商品、20% 退货率、10% 净利率</strong><br>每次退货要付出 3.42 美元的费用（0.36 美元退款管理费 + 0.70 美元 FBT 处理费 + 按 20% 费率计算的 2.36 美元退货运费）。',
    'rr.th.scenario': '情形',
    'rr.th.per100': '每售出 100 件',
    'rr.th.netProfit': '净利润',
    'rr.td.noReturns': '无退货',
    'rr.td.noReturnsCalc': '100 件 × 每件 3.00 美元利润',
    'rr.td.ret20': '20% 退货率（退回 20 件）',
    'rr.td.ret20Calc': '80 件 × 3.00 美元 − 20 件 × 3.42 美元退货成本',
    'rr.td.profitLost': '退货带来的利润损失',
    'rr.p.calc': '退货可能让你的利润少掉一半以上。用我们的<a href="/tools/tiktok-profit-calculator/">利润计算器</a>把退货率算进去，测算你真实的利润率。',
    'rr.h2.reduce': '如何降低退货率',
    'rr.p.reduceIntro': '做得好的 TikTok Shop 卖家会用几套策略把退货控制住：',
    'rr.p.accurate': '<strong>准确的商品listing。</strong>写清尺寸、材质规格和多个角度。买家在下单前掌握的信息越多，退货的可能性就越低。附详细成分表和色号对照表的美妆卖家，退货量少 30-40%。',
    'rr.p.briefs': '<strong>用达人简报设定预期。</strong>给达人明确的指引，说明要展示什么、要讲什么。如果商品偏小，达人应该提一句。如果颜色和视频里略有差异，就把它说清楚。诚实的达人带来更低的退货率。',
    'rr.p.quality': '<strong>履约环节的质量控制。</strong>相比自发货，FBT 履约能减少差错。TikTok 的数据显示，FBT 订单的「错发」和「破损」退货更少。由于自 2026 年初起 FBT 已经是大多数类目的默认履约方式，这是一个内建优势。',
    'rr.p.resellable': '<strong>可二次销售的退货。</strong>并不是所有退回的商品都白白损失。能被检验、重新包装再卖掉的商品，可以收回一部分退货成本。用我们的<a href="/tools/tiktok-profit-calculator/">利润计算器</a>把可二次销售的退货比例设上，就能建模不同的情形。',
    'rr.h2.quick': '快速总结',
    'rr.p.quick': '退货是 TikTok Shop 卖货背后那笔看不见的税。平台冲动驱动的购买模式意味着退货率高于 Amazon，时尚和配饰类目尤其如此。清楚你所在类目的退货率，把它算进定价里，并用现成的工具把损失降到最低。',
    'rr.faq.q1': 'TikTok Shop 的平均退货率是多少？',
    'rr.faq.a1': '全行业 15-20%，按类目从 5%（美妆）到 40%（服饰）不等。',
    'rr.faq.q2': 'TikTok Shop 对退货收费吗？',
    'rr.faq.a2': '会。退款管理费为原始推荐费的 20%，每个 SKU 封顶 $5。自 2026 年 6 月 1 日起，FBT 退货处理费按件收取 &mdash; 非验货通常是 $0.70，验货或重新上架是 $1.00。',
    'rr.faq.q3': '哪个类目的退货率最低？',
    'rr.faq.a4': '美妆与护肤，5-10%；其次是保健／补充剂，5-8%。',
    'rr.faq.q4': '我该怎么降低退货率？',
    'rr.faq.a5': '准确的商品listing、详尽的达人简报、合格的履约，以及可二次销售的退货政策。',
    'rr.p.related': '延伸阅读：<a href="/blog/tiktok-shop-fees-2026/">TikTok Shop 费用 2026</a>（COGS 之前的每一笔费用）&middot; <a href="/blog/tiktok-shop-profit-per-unit-2026/">单件利润公式，一步一步</a>（把退货算进你的模型）。',
    'rr.p.roas': '退货也会改变 ROAS 的底线 &mdash; 在<a href="/tools/tiktok-roas-calculator/">ROAS 计算器</a>里建模吧，它会按你的退货率修正这个门槛。',
    'rr.p.cta': '把退货也算进去，测算你真实的利润率。',
    'rr.next': '← TikTok Shop 账号健康分（AHR）2026：取代违规积分的新体系',
    'rr.disclaimer': '免费的 TikTok Shop 工具。与 TikTok 无关。',
    'sus.meta': 'L.D. Studio 作品 · 2026-08-21 · 阅读约 9 分钟',
    'sus.h1': 'TikTok Shop 账号停用 2026：原因、申诉流程与预防',
    'sus.lede': '账号停用是 TikTok Shop 卖家可能遇到的最昂贵的问题。商品listing 被冻结、广告投放停摆、结算被扣住，而对依赖 TikTok Shop 流量的卖家来说，每停一天都是实打实的收入损失。2026 年风险变得更高：TikTok 把旧的违规积分体系换成了实时的账号健康分（AHR），执法动作也来得更即时。',
    'sus.p.scope': '本文讲清停用到底意味着什么、2026 年账号被停用的几类最常见原因、申诉的具体流程，以及一份在问题出现前就能照着做的预防清单。',
