    'fvs.td.referral': '按买家实付总额收取 6% 推荐费（商品价格加上买家支付的运费）',
    'fvs.th.payment': '支付处理',
    'fvs.td.paymentTiktok': 'TikTok 费率政策中没有列明单独收费',
    'fvs.td.paymentShopify': '每笔线上交易 2.9% + 30¢',
