    'ru.wt.15to16lb': '15–16 磅',
    'ru.p.jul13vs': '<strong>与我们追踪的 6 月 18 日那张卡相比：</strong>多件每件费率是新增的，6 磅到 16 磅的重量档位现在都有了已发布的单件费率（此前 5 磅以上我们只追踪了 5–6 磅和 9–10 磅）。50–150 磅的大件档位在卡上存在，但这里尚未覆盖。',
    'ru.p.jul13means': '<strong>这对你的数字意味着什么：</strong>一个 $29.99、4–8 盎司的商品，单件费用是 $6.32（$1.80 referral + $4.52 FBT）。每单 4 件以上时降到每件 $3.73（$1.80 + $1.93）—— <strong>每件少 $2.59</strong>，按每月 500 件算就是每月 $1,295，还没扣 COGS 和运费。',
    'ru.h2.jun1': '2026 年 6 月 1 日 —— FBT 客户退货处理改为逐项计费',
    'ru.p.jun1': '此前每单固定 <strong>$3.00</strong> 的客户退货处理费，被一张按件计费的费率卡取代。具体收费取决于你选择的退货服务和退回商品的最终处置方式。',
