    'ru.td.rtm': '退回商家',
    'ru.td.rtmRate': '每件退回商品 $0.35',
    'ru.p.jun1means': '<strong>这对你的数字意味着什么：</strong>5% 退货率配不检验处理，现在每件售出商品增加约 $0.035，还没算二次销售或弃置的结果。计算器默认用 $0.70；如果你的退货设置走检验，就改成 $1.00。',
    'ru.h2.jan12': '2026 年 1 月 12 日 —— 多件履约费下调',
    'ru.p.jan12': '自 2026 年 1 月 12 日起，TikTok 把 0–4 磅重量档位内 2 件、3 件和 4 件以上订单的多件履约费下调了<strong>最高 24%</strong>（<a href="https://seller-us.tiktok.com/university/essay?knowledge_id=3507056320268087" target="_blank" rel="noopener"><a href="https://seller-us.tiktok.com/university/essay?knowledge_id=3507056320268087" target="_blank" rel="noopener">来源：TikTok 卖家中心 FBT 费率卡</a></a>）。7 月 13 日那张卡把这项折扣保留到所有重量档位 —— 在 4–8 盎司档，每件最多可省 57%。',
