    'ru.td.perCategoryTable': '依据 <a href="https://seller-us.tiktok.com/university/essay?knowledge_id=5988482086864682" target="_blank" rel="noopener"><a href="https://seller-us.tiktok.com/university/essay?knowledge_id=5988482086864682" target="_blank" rel="noopener">美国类目费率表</a></a>',
