    'tools.photo.faq2a': '不需要。未登录访客每天可以生成 5 张，用 Google 登录后个人每日额度提升到 20 张。可选的 API Key 一栏，是给希望消耗自己模型额度的卖家用的。',
    'tools.photo.faq2q': '我需要 API Key 吗？<span class="sign"></span>',
    'tools.photo.faq3a': '它会额外跑一遍，去掉图片模型容易附带的随机文字与水印，让商品图更贴近 TikTok 的内容规则。该模式默认开启，但仍建议对任何标签或警示区做一次目视检查。',
    'tools.photo.faq3q': '合规免审模式做什么？<span class="sign"></span>',
    'tools.photo.faq4a': '方形（1:1）最适合做头图，因为它在网格图和详情页里都不会被裁切。短视频封面用 9:16，横幅与广告素材用 16:9。',
    'tools.photo.faq4q': '商城主图该用什么比例？<span class="sign"></span>',
    'tools.photo.faq5a': '让模型重新设计商品。永远从真实 SKU 的照片出发，任何改变了形状、颜色、材质、标签或组合内容的输出都要丢弃。准确胜过好看。',
    'tools.photo.faq5q': '卖家在使用 AI 图时最大的错误是什么？<span class="sign"></span>',
    'tools.photo.faq6a': '够覆盖头图、一张场景图和一张短视频封面即可 —— 通常三到四张。免费额度是测试预算，不是指标。一张干净的实物照片，是提升效果最省钱的办法。',
    'tools.photo.faq6q': '每个商品该生成几张图？<span class="sign"></span>',
