    'tools.photo.pit1': '<strong>模型重新设计了商品。</strong>多了按钮、换了盖子、出现现实中不存在的颜色。任何改动商品的输出都要丢弃。',
    'tools.photo.pit2': '<strong>该是标签的地方出现乱码文字。</strong>合规免审模式会自动过滤大部分随机文字，但发布前一定要放大检查标签。',
    'tools.photo.pit3': '<strong>道具改变了报价内容。</strong>摆出组合装观感的构图，会让买家以为会收到不止一件。',
    'tools.photo.pit4': '<strong>颜色过度饱和。</strong>商城里好看、拆箱后失望 —— 退货会让你把整堆费用付两遍。',
    'tools.photo.pit5': '<strong>把整个额度花在几乎一样的图上。</strong>三个真正不同的场景胜过同一角度的十种变化。把免费额度当成测试预算。',
    'tools.photo.rel1': '<a href="/blog/free-ai-product-photos-2026/">免费为 TikTok Shop 生成 AI 商品图</a> —— 这个工具背后的完整流程，从原图到上架。',
    'tools.photo.rel2': '<a href="/blog/best-tiktok-shop-product-research-tools-2026/">各阶段的选品工具</a> —— 先选品；利润真实存在时，做图的成本才划算。',
    'tools.photo.rel3': '<a href="/tools/tiktok-profit-calculator/">利润计算器</a> —— 在为一个素材花掉额度或预算之前，先核对利润率。',
    'tools.photo.rel4': '<a href="/tools/tiktok-fee-calculator/">费用计算器</a> —— 逐项列出 TikTok 的每一笔费用，让你知道一单退货到底要花多少钱。',
