    'tools.sto.embedNote': '按你的栏宽调整 <code>height</code>。所有可嵌入的计算器都列在 <a href="/embed/">ttcalc.shop/embed/</a>。',
    'tools.sto.faq1a': 'FBT 仓储费按每天每立方英尺计，前 60 天免费。从第 61 天起费率随库龄递增：61–90 天每立方英尺每天 $0.03，91–120 天 $0.04，121–180 天 $0.06，181–270 天 $0.12，271–365 天 $0.14，超过 365 天 $0.27。这些费率自 2025 年 12 月 15 日起生效。',
    'tools.sto.faq1q': 'TikTok Shop FBT 仓储费是多少？<span class="sign"></span>',
    'tools.sto.faq2a': '按天。费率卡写明费用按每天 23:59、基于你所有商品占用的总体积计算，包含可售与残次品。那些给出「每月每立方英尺」固定数字的指南，是把中段档位的日费率折算成一个月 —— 每天 $0.03 到 $0.06 约为每月 $0.90 到 $1.80。错的不是算术，而是「固定」这个词：超过 180 天后同一块空间按每天 $0.12 计费，超过一年 $0.27，这不是任何一个单一月度数字能表达的。',
    'tools.sto.faq2q': 'FBT 仓储费是按月收还是按天收？<span class="sign"></span>',
    'tools.sto.faq3a': '费率卡的定义是：仓储天数 = 出库时间 − 入库时间，所以计时从你的库存被接收开始，而不是从你创建发货单、或它离开供应商时开始。',
    'tools.sto.faq3q': '仓储时长怎么算？<span class="sign"></span>',
    'tools.sto.faq4a': '会。官方说明写明仓储费按你所有商品占用的总体积计算，包含可售与残次品。躺在仓库里的残损库存会一直产生费用，直到被移出或弃置，而残次品本身并不赚钱。',
    'tools.sto.faq4q': '残次或不可售的库存也会收仓储费吗？<span class="sign"></span>',
    'tools.sto.faq5a': '费率卡是有意按库龄定价的：超过 180 天的库存按每立方英尺每天 $0.12 计费，是第 61 天费率的四倍；超过一年达到 $0.27。以一件 0.28 立方英尺的商品算，约合每件每天 $0.076 —— 100 件死库存每月约 $227，这还没算它占用的资金。',
    'tools.sto.faq5q': '为什么 180 天后仓储费贵这么多？<span class="sign"></span>',
    'tools.sto.formulaRate': '费率(天数) 随在库时长上升',
