    'tools.sto.noteStorageOnly': '只算仓储 —— 不含履约费、佣金，也不含压在库存里的资金成本。',
    'tools.sto.notes': '费率卡随表附了两条官方说明。仓储费按<strong>每天 23:59</strong>、以你所有商品占用的总体积计算，<em>&ldquo;包含可售与残次品&rdquo;</em> —— 所以残损库存在离开仓库前会一直计费。另外，每个 SKU 每天的最低计费体积为 0.001 立方英尺，只对小于拇指甲的物件才有影响。',
    'tools.sto.p.age': '第 61 天除了费率之外什么都没变。同一块货架空间，到第 366 天要多付九倍的钱，这就是慢销商品双重受创的原因：资金被占住，租金还在涨。',
    'tools.sto.p.allUnits': '退货、残损品和死 SKU 与可售库存一样计费。费率卡对此写得很明确，所以最省钱的仓储决策往往是弃置或清仓价，而不是再付一个月租金。',
    'tools.sto.p.caveat': '有一点要明说：这里建模的是「同时到货、同时出库」的一批货。真实库存是分层老化的，如果你每两周补一次货，实际账单就是所有档位叠在一起的混合值。把结果当成一个决策的成本，而不是你账单的预测。',
    'tools.sto.p.tableAges': '<strong>其他库龄表</strong>把同一批货在 30、60、90、180、270 和 365 天时分别定价。90 天行与 180 天行之间的跳升，是拿给供应商或拿来做采购决策的那个数字：它是你因为订了卖不完的量而主动选择要付的租金。',
    'tools.sto.p.tableDaily': '<strong>逐日表</strong>把你这段持有期按它跨过的档位拆开，于是你能看清究竟是哪一档在推高账单。如果几乎全部费用都落在 181–270 那一行，解法就不是改进包装 —— 而是卖掉、降价或清出货。',
    'tools.sto.p.volume': '仓储费完全不管商品有多重。同一件商品，紧凑的 6×4×2 英寸箱子，费用只有 10×8×6 英寸箱子的五分之一。如果你的包装大部分是空气，那就是在为这些空气按天付租金。',
    'tools.sto.presetFast': '45 天清完',
    'tools.sto.presetSlow': '压 240 天',
