    'tools.cc.faq1a': '按默认输入 —— 售价 $29.99、COGS $6.50、运费 $3.00、头程 $1.00、广告投放 10%、退货率 5% —— 在 20% 的目标利润率下，达人佣金最高约 12.7%。这个上限刚好压在第三方统计的美国均值 ~13% 之下，而且它是上限、不是建议：每多给一个点，都是从你的利润率里扣。',
    'tools.cc.faq1q': '我在 TikTok Shop 上付得起多少达人佣金？<span class="sign"></span>',
    'tools.cc.faq2a': 'TikTok Ads 帮助中心记载联盟佣金可设在 1% 到 80%，并确认同一件商品上定向计划的佣金率会覆盖公开计划的佣金率。TikTok 没有公布官方跨品类均值 —— 别处引用的 ~13% 是第三方估算，不是官方基准。',
    'tools.cc.faq2q': 'TikTok 官方允许的佣金区间是多少？<span class="sign"></span>',
    'tools.cc.faq3a': '本计算器按商品价收达人佣金，与本站所有计算器的口径一致。TikTok 的推荐费才是按买家实付总额（商品价加上买家支付的运费）计收的那一项。两笔费用的基数不同，这也是为什么在多数订单上，20% 的达人佣金在金额上高于 6% 的推荐费。',
    'tools.cc.faq3q': '达人佣金按商品价算，还是按买家实付总额算？<span class="sign"></span>',
    'tools.cc.faq4a': '要，只要你给达人寄样品。一件 COGS $6.50 的商品寄出十件，就是送掉 $65 的库存 —— 这是真实成本，属于单件账的一部分。计算器的摊销方式是：样品件数 × 单件样品成本 ÷ 当月销量。按月销 100 件算，这十件样品给每一笔订单增加 $0.65 的成本。',
    'tools.cc.faq4q': '算佣金时要把免费样品算进去吗？<span class="sign"></span>',
    'tools.cc.faq5a': '两个常见原因。第一，很多计算器只在商品价上算推荐费，漏掉了 TikTok 计进费基的买家支付运费。第二，有些计算器把支付手续费单列为 2.9% + $0.30 —— TikTok 美国站在 2024 年 4 月统一 6% 费率生效时已废止该结构；TikTok 公布的收费政策里没有单独的交易手续费。',
    'tools.cc.faq5q': '为什么我的盈亏平衡佣金率和别的计算器不一样？<span class="sign"></span>',
    'tools.cc.formulaFloor': '底线 = 营收 − 推荐费 − FBT − COGS − 运费 − 头程 − 仓储 − 广告 − 样品摊销 − 退货成本',
