    'tools.cc.methodLede': '本站其它计算器都是正向跑的：给一个费率，告诉你每件剩下多少。这个反过来算，而且算式是精确解，不是近似值。',
    'tools.cc.p.above30': '很少见 —— 通常是 COGS 极低或客单价很高的商品。到了这个量级，佣金这一行的数字会盖过所有 TikTok 费用之和，所以在发布计划之前，样品成本和佣金追回风险值得再看一遍。',
    'tools.cc.p.bases': 'TikTok 的推荐费按买家实付总额计算（商品价<em>加上</em>买家支付的运费）；本页的达人佣金按商品价计算。在一件 $29.99 的商品上，6% 推荐费（$1.80）与 6% 达人佣金（$1.80）刚好相等 —— 但只要加上 $5 买家支付的运费，推荐费会跟着变大，而达人佣金不会。',
    'tools.cc.p.below5': '这件商品基本养不起达人计划。要么先修单件经济性（COGS、FBT 档位、退货率），要么只在利润率更深的那一小部分 SKU 上跑达人计划。',
    'tools.cc.p.benchmark': '看到任何精确到小数点的均值 —— 包括我们这里引用的 —— 都当基准看，别当规则。真正要紧的是上面你自己算出来的那个率。计划机制、佣金追回与费率策略的完整拆解在<a href="/blog/tiktok-shop-affiliate-program-2026/">联盟计划指南</a>里。',
    'tools.cc.p.blended': '有一句提醒适用于所有档位：真正要紧的是你的<em>混合</em>佣金率。如果达人带来一半订单，那么 20% 的公开计划费率对生意而言是平均每单 10%。情景表展示的是「单笔达人订单」的经济性；除以达人订单占比，就得到混合视角。',
    'tools.cc.p.fifteenToThirty': '有竞争力的区间。你可以在公开计划上对标甚至跑赢市场均值，同时保住目标利润率。留意混合佣金率：如果只有部分订单带佣金，你的平均成本会低于名义费率。',
    'tools.cc.p.fiveToFifteen': '付得起，但低于第三方统计的美国均值 —— 达人接单意愿会比开 15%+ 的竞争对手更弱。这时定向邀约具体达人，比公开计划上那个数字更重要。',
    'tools.cc.p.floor': '这条底线是产品在付出一分钱达人佣金之前、每件能赚到的钱。它正好等于利润计算器在 0% 佣金率下的实际利润。',
    'tools.cc.p.solve': '达人佣金是商品价的一个百分比，所以这个方程是线性的，解也是精确的。把目标利润设成 $0，你就得到盈亏平衡佣金率 —— 也就是这件商品开始一分钱都不给你赚的那个点。',
