    'tools.fbt.faq1a': '两条官方规则，2026 年 5 月 1 日生效。重量等于或低于 2 磅、且体积（长 × 宽 × 高）等于或低于 332 立方英寸的商品，只按实际重量计费。其余一切按实际重量与体积重中的较大者计费，体积重 = 长 × 宽 × 高 ÷ 166。',
    'tools.fbt.faq1q': 'FBT 的计费重是怎么算的？<span class="sign"></span>',
    'tools.fbt.faq2a': '166。一个 10×8×6 英寸的箱子是 480 立方英寸，480 ÷ 166 得到 2.9 磅体积重。如果你看到 TikTok FBT 用 139 作除数，那是常见的国内包裹除数，不是 TikTok 的数字 —— 用它会把体积重高估约 19%。',
    'tools.fbt.faq2q': 'TikTok FBT 的体积重除数是多少？<span class="sign"></span>',
    'tools.fbt.faq3a': '官方准入脚注把单件上限定为实际重量 150 磅、最长边 108 英寸。本站的单件费率卡覆盖 4 盎司到 16 磅；2026 年 7 月 13 日起，超过 50 磅的商品转入扩展的重货/大件档位，按另一套价目表计价，本计算器不做建模。',
    'tools.fbt.faq3q': 'FBT 的商品最大可以多大？<span class="sign"></span>',
    'tools.fbt.faq4a': '取决于你谈下来的面单费率和你的 3PL 报价，所以对比行把你的数字作为输入。FBT 打包进去的是：前 60 天免费的仓库仓储，以及每件退货 $0.70（非检验）或 $1.00（检验）的逐项退货处理费。如果这个对比只有在你的时间免费时才成立，那它就不是对比。',
    'tools.fbt.faq4q': 'FBT 比自己发货便宜吗？<span class="sign"></span>',
    'tools.fbt.faq5a': '能，前提是体积重在起决定作用。这对预设发的是同一件 8 盎司商品：装在 10×8×6 英寸箱子里按 2.9 磅体积重计费（$6.27）；装在 6×4×2 英寸箱子里则按它实际的半磅重量计费（$4.52）。光是箱子每件就省 $1.75 —— 100 件就是每月 $175。',
    'tools.fbt.faq5q': '换更小的包装真的能省下一整个 FBT 档位吗？<span class="sign"></span>',
    'tools.fbt.formulaGreater': '计费重 = max(实际重量, 长×宽×高 ÷ 166)',
    'tools.fbt.formulaLight': '重量 ≤ 2 磅 且 长×宽×高 ≤ 332 立方英寸 → 按实际重量计费',
