    'tools.fbt.limitsLede': '官方页面上有两组上限。这里说明各自管什么。',
    'tools.fbt.methodLede': 'TikTok 的费率卡把规则写成两条分支，自 2026 年 5 月 1 日生效。这个计算器严格按原文实现。',
    'tools.fbt.p.fbtIncludes': '从 TikTok 仓库拣货、打包、发货，前 60 天免费的仓储，以及逐项计费的退货处理（每件退货非检验 $0.70 / 检验 $1.00）。60 天之后，仓储按每天每立方英尺计费，并随库龄上升 —— <a href="/tools/tiktok-fbt-storage-calculator/">仓储费计算器</a>算的就是这部分，利润计算器则把它当作一项输入。',
    'tools.fbt.p.greater': '任一阈值被突破，体积重就进入比拼。体积大却很轻的商品 —— 枕头、狗玩具、美妆套装 —— 常常被收到比秤重高出两三个档位。',
    'tools.fbt.p.light': '大多数小而密的商品落在这里。如果你的单件等于或低于 2 磅<em>且</em>包装体积在 332 立方英寸以内，箱子多大都无所谓 —— 秤说了算。',
    'tools.fbt.p.limits': '超过 50 磅、或边长在 26–32 英寸之间的商品会转入扩展的重货/大件服务 —— 分档一直到 150 磅与 108 英寸，按另一套价目表计价，本站不做建模。如果计算器提示你的单件超出费率卡，在敲定利润率之前先找你的 TikTok 客户经理报价。',
    'tools.fbt.p.selfIncludes': '你每件的面单加包装 —— 而且老实说，还有你的时间：履约、录入物流单号、退货流程，全都回到你身上。如果一个对比只有在你的时间被算作零时才成立，那它就不是对比。',
    'tools.fbt.p.threePLIncludes': '你的 3PL 拣货 + 打包 + 发货的每件报价，再加上按月最低消费摊到销量上的部分。报价随尺寸和季节差异极大 —— 填你真实费率卡上的数字，别填宣传页上的。',
    'tools.fbt.p.tiers': '每个档位和两张价格表都列在<a href="/blog/tiktok-shop-fbt-fulfillment-guide-2026/">FBT 履约指南</a>和<a href="/fee-schedule/">费率表</a>里。最常被搞错的是除数：TikTok 除以 <strong>166</strong>。有些指南写 139 —— 那是常见国内包裹的除数 —— 它会把体积重虚高约 19%，把你吓出本来够得着的档位。',
    'tools.fbt.p.warehouse': '官方脚注写得很明确：<em>“单件实际重量由 FBT 仓库在入仓处理时测定。”</em>你的厨房秤只是估算；他们的入仓扫描才是账单。上架前称一件打包好的成品样品。',
    'tools.fbt.p.whyInputs': 'TikTok 没有公布自发货或 3PL 费率，本站也不会凭空造数字。任何把“典型”3PL 费用写死的工具，都是在替你猜；这里由你带来真实报价，算式才诚实。',
    'tools.fbt.presetBulky': '10×8×6 英寸箱',
    'tools.fbt.presetCompact': '6×4×2 英寸箱',
    'tools.fbt.presetsLabel': '同一件商品，两种箱子：',
    'tools.fbt.quickAnswer': '默认输入发的是一件 <strong>8 盎司商品，装在 10×8×6 英寸的箱子里</strong>。这个箱子是 480 立方英寸，所以体积重（480÷166 = 2.9 磅）起决定作用，FBT 按 <strong><span id="qa_weight">2–3 磅</span> 档位计费：每件 $6.27</strong>。把同一件商品换进 6×4×2 英寸的箱子，官方的 2 磅 / 332 立方英寸阈值就适用了 —— 它按实际的半磅重量计费，<strong>$4.52</strong>。光是箱子就值 <strong>每件 $1.75</strong>，按月销 100 件算约 <strong>每月 $175</strong>。FBT 的准入上限是 150 磅、最长边 108 英寸。',
    'tools.fbt.ratesLede': '这个计算器读取的单件费率卡从 ≤4 盎司（$4.28，单件）一直到 15–16 磅（$12.67），自 2026 年 7 月 13 日生效。同一卖家在一次结账中的多件订单会让单件费用大幅下降 —— 一笔 4 件的订单按档位不同落在每件 $1.56–$4.54。',
    'tools.fbt.rel1': '<a href="/blog/tiktok-shop-fbt-fulfillment-guide-2026/">FBT 履约指南 2026</a> —— 每个重量档位，以及多件订单是怎么计价的。',
    'tools.fbt.rel2': '<a href="/blog/tiktok-shop-fbt-fee-per-unit-2026/">FBT 每件费用</a> —— 整张费率卡上履约真实要花多少。',
    'tools.fbt.rel3': '<a href="/tools/tiktok-fbt-storage-calculator/">TikTok Shop 仓储费计算器</a> —— 每立方英尺每天压着库存要花多少。',
    'tools.fbt.rel4': '<a href="/blog/tiktok-shop-return-rates-cost-2026/">退货率与它的成本</a> —— 本计算器加的那条拖累背后的退货项。',
    'tools.fbt.rel5': '<a href="/tools/tiktok-profit-calculator/">TikTok Shop 利润计算器</a> —— 把这个档位代进完整的单件利润算式。',
