    // TikTok Shop vs Amazon FBA page: prose, panel and dynamic copy (batch 25)
    'seclabel.01decisionGuide': '01 / 决策指南',
    'seclabel.02feeComparison': '02 / 费用对比',
    'seclabel.04sensitivity': '04 / 敏感度',
    'tools.va.cell.fuel': '$0.14（履约费的 3.5%）',
    'tools.va.cell.fulfillAmz': '$4.10（FBA）',
    'tools.va.cell.fulfillTts': '$4.52（FBT，4–8 盎司）',
    'tools.va.cell.lowInv': '$0.36（<28 天库存）',
    'tools.va.cell.w1': 'TikTok +$1.33',
    'tools.va.cell.w2': '亚马逊 +$3.16',
    'tools.va.cell.w3': '亚马逊 +$7.66',
    'tools.va.faq1a': '在默认商品上是：$6.32 的 TikTok 费用对 $9.46 的亚马逊费用，净利润 $10.96 对 $9.62。但这不是一个固定的事实 —— 把 TikTok 的达人佣金率提到 15%，亚马逊就以每件 $3.16 反超。',
    'tools.va.faq1q': 'TikTok Shop 比亚马逊 FBA 便宜吗？<span class="sign"></span>',
    'tools.va.faq2a': 'FBA 履约费上 3.5% 的燃油附加费、入库配置费（默认输入下每件 $0.36）、库存覆盖跌到 28 天以下时的低库存费（$0.36），以及每件 $0.30 的最低佣金（低于 $10 时还要加 $0.05 成交费）。“15% 佣金率”那种比法把这些全漏掉了。',
    'tools.va.faq2q': '亚马逊有哪些收费是卖家容易忘算的？<span class="sign"></span>',
    'tools.va.faq3a': '当你要付给达人很高佣金时，当商品又重又便宜时，或者当需求是搜索驱动而不是冲动驱动时。另外，凡是你在 TikTok 上不得不花钱买下全部流量的品类，亚马逊也赢。',
    'tools.va.faq3q': '亚马逊 FBA 究竟在什么时候能真的赢过 TikTok Shop？<span class="sign"></span>',
    'tools.va.faq4a': '只比明面佣金的话，轻松赢。但比到整摞费用，差距就收窄了 —— 因为 TikTok 一平到底的 FBT 常常比它的佣金还大，而亚马逊把履约打包进了更少的几条费用里。比总额，别比百分比。',
    'tools.va.faq4q': 'TikTok 6% 的佣金率真的能赢过亚马逊的 15% 吗？<span class="sign"></span>',
    'tools.va.faq5a': '通常是应该的 —— 两个渠道接的是不同的需求：亚马逊上是搜索驱动的买家，TikTok 上是风潮驱动的冲动买家。很多卖家让亚马逊承接基础的长尾销量、让 TikTok 承接爆发，同一个 SKU 上挂着两套成本结构。',
    'tools.va.faq5q': '我应该两个平台都卖吗？<span class="sign"></span>',
    'tools.va.faq6a': '两个渠道都要为无法二次销售的退货承担损失的货成本 —— 在这里是 5% 退货率、50% 可二次销售下每件 $0.16。TikTok 在上面再加一笔 FBT 退货处理费，而两边在退款时都会留下佣金的 20%，每个 SKU 上限 $5。',
    'tools.va.faq6q': '退货会怎么影响这个对比？<span class="sign"></span>',
