    'tools.va.labelReturnHandling': 'TikTok FBT 退货处理费（每件退货）',
    'tools.va.labelShipAmz': '你发到亚马逊运营中心的头程运费（每件）',
    'tools.va.labelShipChargeAmz': '向买家收取的运费 —— 亚马逊',
    'tools.va.labelShipChargeTts': '向买家收取的运费 —— TikTok',
    'tools.va.labelShipTts': '你在 TikTok 上的运费（每件）',
    'tools.va.lede': '同一件商品，两个平台。扣完所有费用之后，到底哪个真正让你赚得更多？',
    'tools.va.lever.cogs': '<strong>货成本。</strong>低货成本对两边都好，但在 TikTok 上更关键，因为 FBT 已经在一件便宜商品上吃掉了一大块。',
    'tools.va.lever.demand': '<strong>搜索需求。</strong>如果买家是把商品名敲进搜索框的，亚马逊就永久免费地接住了这批需求；而 TikTok 每周都得重新争取一次。',
    'tools.va.lever.reach': '<strong>自然流量。</strong>TikTok 上每一分不靠付费买来的成交额，都在降低 TikTok 的实际广告负担 —— 这是视频优先的 marketplace 能给出的最大的结构性优势。',
    'tools.va.lever.weight': '<strong>重量。</strong>FBT 是一件一计费的固定费用，随重量陡峭上升；FBA 的履约费也会涨，但走的是另一条曲线。重货可以把赢家换掉。',
    'tools.va.p.amzWins': '你卖的是货成本高的商品，成交主要靠自然搜索而不是付费视频，或者你要给达人付很高的佣金。Prime 配送养着购物车按钮，而长尾搜索活得过任何一阵风潮。',
    'tools.va.p.both': '大多数多渠道卖家让亚马逊承接长尾的自然需求，让 TikTok Shop 承接风潮带来的冲动下单。同一个 SKU，两拨受众，两套完全不同的利润结构。',
    'tools.va.p.exampleLede': '每一个数字都是计算器在默认输入下自己算出来的：$29.99 售价、$6.50 货成本、发往亚马逊的头程 $1.20 对比 TikTok 的 $3.00、两个渠道都不向买家收运费、两边各 10% 广告支出、5% 退货率且其中一半可二次销售，以及 0% 的 TikTok 达人佣金率。',
    'tools.va.p.exampleResult': 'TikTok 每件多赚 $1.33 —— 同一件商品上大约多 14% 的利润。数字按计算器显示的结果为准；显示时的四舍五入可能与逐行相加相差一分钱。',
    'tools.va.p.levers': '除了达人佣金，还有四个杠杆会推动这个对比：',
    'tools.va.p.sensLede': '上面什么都没变，只改 TikTok 的达人佣金率 —— 同样的售价、同样的货成本、同样的广告、同样的退货率：',
    'tools.va.p.sensNote': '仅仅一个输入，就能把结果从“TikTok 多赚 14%”甩到“TikTok 少赚 80%”。这就是“哪个平台更好”的诚实答案 —— 它取决于你自己能控制的那些条件，而不是挂在明面上的佣金率。',
    'tools.va.p.stackGap': '在这件商品上，亚马逊的费用重了 $3.14。还要留意两边各自在什么地方对自己的局限说得坦白：TikTok 的 FBT 是一件一计费的固定值，所以你的商品变便宜时它不会跟着变小。而亚马逊的燃油附加费、入库配置费和低库存费，都是“15% 佣金率”那种比法悄悄漏掉的加项。',
    'tools.va.p.stacks': '亚马逊挂在明面上的佣金率（15%）是 TikTok 的两倍还多（<a href="https://seller.tiktokglobalshop.com/university/essay?knowledge_id=140687984494338&amp;role=1&amp;shop_region=US" target="_blank" rel="noopener">6%，见 TikTok 美国佣金政策</a>）。两边的费率都按买家支付总额收取 —— 商品加运费，亚马逊还要加上礼品包装费 —— 所以这个工具给每个渠道都留了一个“向买家收取的运费”字段。真正把差距抹平的是底下的东西：亚马逊的履约与附加费那一摞，对上 TikTok 一平到底的<a href="https://seller-us.tiktok.com/university/essay?knowledge_id=3507056320268087" target="_blank" rel="noopener">FBT 费率卡</a>。',
    'tools.va.p.ttsWins': '你卖的是正在起势、冲动下单、货成本低、视觉冲击力强的商品。视频转化率高，所以自然流量可以顶替掉一部分广告支出，而 FBT 在轻小件上很便宜。',
    'tools.va.pitfall.feesOnly': '<strong>只看费用就下结论。</strong>货成本、商品重量、以及需求是不是搜索驱动的，它们对结果的影响都比费用行更大。先跑一遍你自己的数字，再选渠道。',
    'tools.va.pitfall.inbound': '<strong>忽视头程运费的不对称。</strong>亚马逊把库存摊到各个运营中心；TikTok FBT 则是整批进它自己的仓。这里分别是每件 $1.20 和 $3.00 —— 一个实实在在的差距，跟佣金一点关系都没有。',
    'tools.va.pitfall.rates': '<strong>只比挂在明面上的佣金率。</strong>6% 对 15% 是这个对比的开头，不是答案。在默认商品上，两边总额是 $6.32 和 $9.46 —— 比这些百分比暗示的差距要窄得多。',
    'tools.va.pitfall.surcharges': '<strong>漏掉亚马逊的附加费。</strong>燃油附加费、入库配置费和低库存费合起来在这里是每件 $0.86。任何只建立在“15% 佣金”上的对比，都是在低估亚马逊。',
    'tools.va.pitfall.traffic': '<strong>以为 TikTok 的流量是免费的。</strong>自然视频能撑起一场发布，但大多数卖家至少还是要买一部分触达。这笔支出直接落到利润最后一行，这也是为什么上面给两边都套用了标准的 10% 广告假设。',
    'tools.va.quickAnswer': '默认商品（$29.99、货成本 $6.50、5% 退货率）下，TikTok Shop 收的平台费是 <strong>$6.32</strong>，亚马逊 FBA 是 <strong>$9.46</strong>，净利润则是 <strong>$10.96 对 $9.62</strong>：TikTok 每件领先 $1.33，利润率 36.5% 对 32.1%。但这个领先很脆弱 —— 把达人佣金加到 15%，TikTok 就掉到每件 $6.46，让亚马逊反超 $3.16。这里每个数字都假设两个渠道都不向买家收运费，所以两边的佣金基数都只是商品售价本身。',
    'tools.va.rel1': '<a href="/tools/tiktok-profit-calculator/">利润计算器</a> —— 完整的单件利润，含仓储、头程运费和广告支出。',
    'tools.va.rel3': '<a href="/tools/tiktok-roas-calculator/">ROAS 计算器</a> —— 广告那一侧的算式，以及你的盈亏平衡底线。',
    'tools.va.rel4': '<a href="/blog/tiktok-shop-vs-amazon-fba-2026/">2026 年的 TikTok Shop 对比亚马逊 FBA</a> —— 这个工具背后那篇写透的对比。',
    'tools.va.rel5': '<a href="/blog/tiktok-shop-fees-vs-shopify-2026/">TikTok Shop 费用对比 Shopify</a> —— 第三种开店选择，以及它每单要花多少。',
    'tools.va.rel6': '<a href="/blog/tiktok-shop-fbt-fee-per-unit-2026/">FBT 每件费用</a> —— 这个对比里的履约那一侧，一档一档拆。',
    'tools.va.resultsTitle': '并排对比',
